DECLARE r jsonb := '{"industry_code": "IND_WAT_001", "industry_name": "Water Resources, Environment and Public Utilities", "domain_code": "IND_WAT_D02", "domain_name": "Environmental Data and Analysis", "family_code": "WAT_RF08", "family_name": "Monitoring Devices and Sensor Evidence", "role_code": "WAT_RF08_DR01", "role_name": "Water Monitoring Technology Associate", "description": "Water Monitoring Technology Associate supports support digital monitoring systems in the RAREMINDS River Mission workplace case. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.", "observable_behaviours": "Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L2 instrument and sampling metadata → L3 dashboard exceptions → L5 monitoring-technology route. Inputs: device registry, monitoring station metadata, time fields, sensor-series logs and device-fault/maintenance evidence. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP03, CAP04, CAP06. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.", "typical_work_activities": "Water Monitoring Technology Associate: Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Device/station mapping register; Timestamp-reconciliation and missing-data log; Monitoring dashboard exception report; Sensor fault and technical-support handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP03 Monitoring plan; CAP04 Sampling and test record; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "RIC (Realistic/Investigative/Conventional): R fits field instruments and device constraints; I fits diagnostics and anomaly detection; C fits time-series consistency and traceability. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Tech Electrical and Electronics Engineering; B.Tech Electronics and Communication Engineering; B.Tech Instrumentation Engineering; B.Tech Computer Science Engineering; B.Tech Information Technology; BCA; MCA; B.Sc. Data Science; B.Sc. Artificial Intelligence", "apt_verbal_reasoning": 63, "apt_logical_reasoning": 94, "apt_numerical_reasoning": 90, "apt_data_interpretation": 96, "apt_pattern_recognition": 96, "apt_spatial_reasoning": 85, "big5_openness": 5, "big5_conscientiousness": 5, "big5_extraversion": 2, "big5_agreeableness": 3, "big5_emotional_stability": 4, "value_impact": 5, "value_status": 3, "value_autonomy": 4, "value_security": 4, "value_financial": 4, "value_lifestyle": 3, "value_creativity": 5, "value_leadership": 3, "aptitude_areas": "Pattern Recognition|Data Interpretation|Logical Reasoning", "aptitude_rationale": "Detect missing intervals, mismatched timestamps, device faults and inconsistent monitoring data. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required.", "big_five_traits": "Conscientiousness|Openness|Emotional Stability", "big_five_rationale": "Systematic diagnostics and careful exception documentation prevent false monitoring conclusions. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria.", "work_values_list": "Impact|Creativity|Autonomy", "work_values_rationale": "The work supports useful technical innovation, but a device fault record is not an instrument-calibration certificate. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees.", "profile": {"description": "Water Monitoring Technology Associate supports support digital monitoring systems in the RAREMINDS River Mission workplace case. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.", "observable_behaviours": "Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner; Check each saved record against source ID, units, errors and role authority.", "role_work_context": "L2 instrument and sampling metadata → L3 dashboard exceptions → L5 monitoring-technology route. Inputs: device registry, monitoring station metadata, time fields, sensor-series logs and device-fault/maintenance evidence. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP03, CAP04, CAP06. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.", "typical_work_activities": "Water Monitoring Technology Associate: Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.", "role_output_evidence": "Source-backed outputs: Device/station mapping register; Timestamp-reconciliation and missing-data log; Monitoring dashboard exception report; Sensor fault and technical-support handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP03 Monitoring plan; CAP04 Sampling and test record; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.", "primary_riasec": "R", "secondary_riasec": "I", "tertiary_riasec": "C", "riasec_reason": "RIC (Realistic/Investigative/Conventional): R fits field instruments and device constraints; I fits diagnostics and anomaly detection; C fits time-series consistency and traceability. Proposed role-environment orientation, not an individual assessment.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Tech Electrical and Electronics Engineering; B.Tech Electronics and Communication Engineering; B.Tech Instrumentation Engineering; B.Tech Computer Science Engineering; B.Tech Information Technology; BCA; MCA; B.Sc. Data Science; B.Sc. Artificial Intelligence", "riasec_code_string": "RIC", "aptitude_profile": {"verbal_reasoning": 63, "logical_reasoning": 94, "numerical_reasoning": 90, "data_interpretation": 96, "pattern_recognition": 96, "spatial_reasoning": 85}, "big_five_profile": {"openness": 5, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 3, "creativity": 5, "leadership": 3}, "aptitude_assessment": {"areas": ["Pattern Recognition", "Data Interpretation", "Logical Reasoning"], "rationale": "Detect missing intervals, mismatched timestamps, device faults and inconsistent monitoring data. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required."}, "big5_assessment": {"traits": ["Conscientiousness", "Openness", "Emotional Stability"], "rationale": "Systematic diagnostics and careful exception documentation prevent false monitoring conclusions. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria."}, "work_values_assessment": {"values": ["Impact", "Creativity", "Autonomy"], "rationale": "The work supports useful technical innovation, but a device fault record is not an instrument-calibration certificate. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees."}}, "embedding_text": "ROLE\nName: Water Monitoring Technology Associate\n\nCAREER CONTEXT\nIndustry: Water Resources, Environment and Public Utilities\nDomain: Environmental Data and Analysis\nRole Family: Monitoring Devices and Sensor Evidence\n\nROLE SUMMARY\nWater Monitoring Technology Associate supports support digital monitoring systems in the RAREMINDS River Mission workplace case. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.\n\nWORK CONTEXT\nL2 instrument and sampling metadata → L3 dashboard exceptions → L5 monitoring-technology route. Inputs: device registry, monitoring station metadata, time fields, sensor-series logs and device-fault/maintenance evidence. Course-wide foundations: CAP01, CAP02, CAP06, CAP07, CAP08, CAP11. Role focus: CAP03, CAP04, CAP06. May assess monitoring data and document device faults; cannot calibrate uncertified instruments, alter safety-critical devices or certify missing readings as valid.\n\nTYPICAL WORK ACTIVITIES\nWater Monitoring Technology Associate: Check device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner. When source evidence is missing, record a HOLD/exception and identify the reviewing owner.\n\nKEY RESPONSIBILITIES & ACTIONS\nCheck device IDs and expected reporting intervals; Compare actual timestamps and station identifiers; Flag missing, duplicated or conflicting sensor readings; Record device exceptions and route them to the technical owner; Check each saved record against source ID, units, errors and role authority.\n\nDELIVERABLES & OUTPUTS\nSource-backed outputs: Device/station mapping register; Timestamp-reconciliation and missing-data log; Monitoring dashboard exception report; Sensor fault and technical-support handover. Associated capability evidence: CAP01 Investigation brief; CAP02 Stakeholder and site register; CAP03 Monitoring plan; CAP04 Sampling and test record; CAP06 Validated analytical workbook; CAP07 Evidence and hypothesis matrix; CAP08 Criteria comparison and gap report; CAP11 Final professional investigation portfolio.\n\nINTEREST AND WORK-STYLE ALIGNMENT\nRIC (Realistic/Investigative/Conventional): R fits field instruments and device constraints; I fits diagnostics and anomaly detection; C fits time-series consistency and traceability. Proposed role-environment orientation, not an individual assessment.\n\nAPTITUDE ALIGNMENT\nKey areas: Pattern Recognition, Data Interpretation, Logical Reasoning\nReadiness: Detect missing intervals, mismatched timestamps, device faults and inconsistent monitoring data. These are draft importance estimates for role requirements, not learner aptitude scores; SME review required.\n\nBEHAVIOURAL ALIGNMENT\nKey traits: Conscientiousness, Openness, Emotional Stability\nWork style: Systematic diagnostics and careful exception documentation prevent false monitoring conclusions. Trait-demand ratings are provisional role descriptors, not personality diagnosis or exclusion criteria.\n\nWORK-VALUE ALIGNMENT\nKey values: Impact, Creativity, Autonomy\nMotivation: The work supports useful technical innovation, but a device fault record is not an instrument-calibration certificate. Work-value ratings are provisional career-exploration descriptors, not employment or pay guarantees.\n\nEDUCATION AND ELIGIBILITY\nGate: Preferred\nStreams: B.Tech Electrical and Electronics Engineering; B.Tech Electronics and Communication Engineering; B.Tech Instrumentation Engineering; B.Tech Computer Science Engineering; B.Tech Information Technology; BCA; MCA; B.Sc. Data Science; B.Sc. Artificial Intelligence\n"}'::jsonb;
 i uuid; d uuid; f uuid; roleid uuid; scopeid uuid; familyid uuid; contextid uuid; existing jsonb;
BEGIN

 i:=pg_temp.river_entity('industries',r->>'industry_code',r->>'industry_name','081cf05d-7a89-5c4a-897f-bde339d91318'::uuid);
